using System;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

public class IncreasePurifyReceivedByEnemiesOmenData : OmenData
{
	private const string IncreasePurifyReceivedByEnemiesID = "IncreasePurifyReceiveByEnemies";

	[Header("Increase Purify Received By Enemies")]
	[SerializeField]
	protected int additionalPurifyAmount;

	private Func<int, int> purifyOmenAction;

	public override void Initialize(OmenInstance omenInstance)
	{
		purifyOmenAction = GetPurifyOmenAction(omenInstance);
		ReferenceSingleton<PurifyOmensHandler>.Instance.OnEnemyReceivePurifyModifierOmenActions.Add(purifyOmenAction);
	}

	public virtual Func<int, int> GetPurifyOmenAction(OmenInstance omenInstance)
	{
		return delegate(int purifyAmount)
		{
			purifyAmount += additionalPurifyAmount;
			return purifyAmount;
		};
	}

	public override void OmenRemoved()
	{
		ReferenceSingleton<PurifyOmensHandler>.Instance.OnEnemyReceivePurifyModifierOmenActions.Remove(purifyOmenAction);
	}

	protected string GetIncreasePurifyReceivedByEnemiesLocalizedString()
	{
		return GetIncreasePurifyReceivedByEnemiesLocalizedString(additionalPurifyAmount);
	}

	public string GetIncreasePurifyReceivedByEnemiesLocalizedString(int externalAdditionalPurifyAmount)
	{
		return Smart.Format(ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedString("IncreasePurifyReceiveByEnemies"), externalAdditionalPurifyAmount);
	}
}
